-- Migration 0002: seed IANA DHCPv4 option catalog
--
-- Source: IANA "BOOTP Vendor Extensions and DHCP Options" registry
-- (https://www.iana.org/assignments/bootp-dhcp-parameters/). Covers every
-- ASSIGNED DHCPv4 option code from 1-254. Options 0 (Pad) and 255 (End) are
-- protocol markers, not configurable values, and are intentionally omitted.
-- Codes not listed here (e.g. gaps like 84, 96, 111, 126, 127, 144, 161-174,
-- 178-207, 214-219, 222-223, 224-254 minus the explicitly-assigned ones
-- below) are Unassigned or Reserved in the registry as of this writing and
-- are skipped per the task instructions.
--
-- value_type is constrained by migration 0001 to:
--   string, uint8, uint16, uint32, ip, ip_list, bytes, boolean, fqdn, route_list

BEGIN;

ON CONFLICT (option_code) DO NOTHING;

COMMIT;
