INSERT INTO dhcp_option_catalog (option_code, name, value_type, description, iana_reference)
VALUES
  (1, 'subnet_mask', 'ip', 'Specifies the client''s subnet mask as defined in RFC 950. If both this option and the Router option are specified in a DHCP reply, this option must be inserted before the Router option.', 'RFC 2132'),
  (2, 'time_offset', 'uint32', 'Specifies the offset of the client''s subnet in seconds from Coordinated Universal Time (UTC). The offset is expressed as a signed 32-bit integer stored in this unsigned field, with positive offsets east of the zero meridian.', 'RFC 2132'),
  (3, 'routers', 'ip_list', 'Lists the IP addresses of routers on the client''s subnet, in order of preference. The client should install the first reachable router as its default route.', 'RFC 2132'),
  (4, 'time_servers', 'ip_list', 'Lists the IP addresses of RFC 868 time servers available to the client.', 'RFC 2132'),
  (5, 'name_servers', 'ip_list', 'Lists the IP addresses of IEN 116 name servers available to the client. This is a legacy option largely superseded by option 6 (DNS servers).', 'RFC 2132'),
  (6, 'domain_name_servers', 'ip_list', 'Lists the IP addresses of Domain Name System (DNS) servers available to the client, in order of preference.', 'RFC 2132'),
  (7, 'log_servers', 'ip_list', 'Lists the IP addresses of MIT-LCS UDP log servers available to the client.', 'RFC 2132'),
  (8, 'cookie_servers', 'ip_list', 'Lists the IP addresses of RFC 865 Quote of the Day servers available to the client.', 'RFC 2132'),
  (9, 'lpr_servers', 'ip_list', 'Lists the IP addresses of RFC 1179 Line Printer servers available to the client.', 'RFC 2132'),
  (10, 'impress_servers', 'ip_list', 'Lists the IP addresses of Imagen Impress servers available to the client.', 'RFC 2132'),
  (11, 'resource_location_servers', 'ip_list', 'Lists the IP addresses of RFC 887 Resource Location servers available to the client.', 'RFC 2132'),
  (12, 'host_name', 'string', 'Specifies the name of the client, which may be a fully qualified domain name. The client may use this value to set its own hostname.', 'RFC 2132'),
  (13, 'boot_file_size', 'uint16', 'Specifies the length in 512-octet blocks of the default boot image for the client.', 'RFC 2132'),
  (14, 'merit_dump_file', 'string', 'Specifies the path name of a file to which the client''s core image should be dumped in the event of a client crash.', 'RFC 2132'),
  (15, 'domain_name', 'string', 'Specifies the domain name the client should use when resolving hostnames via the Domain Name System.', 'RFC 2132'),
  (16, 'swap_server', 'ip', 'Specifies the IP address of the client''s swap server.', 'RFC 2132'),
  (17, 'root_path', 'string', 'Specifies the path name that contains the client''s root disk, used for clients that boot with a remote root filesystem such as diskless workstations.', 'RFC 2132'),
  (18, 'extensions_path', 'string', 'Specifies the name of a file, retrievable via TFTP, that contains additional vendor-extension-format options to be interpreted the same as the DHCP vendor extension field.', 'RFC 2132'),
  (19, 'ip_forwarding', 'boolean', 'Enables or disables IP layer packet forwarding on the client, overriding the client''s default behavior.', 'RFC 2132'),
  (20, 'non_local_source_routing', 'boolean', 'Enables or disables the forwarding of datagrams with non-local source routes, overriding the client''s default behavior.', 'RFC 2132'),
  (21, 'policy_filter', 'ip_list', 'Specifies policy filters for non-local source routing, given as address/mask pairs; datagrams with a non-local source route not matching one of the filters are discarded.', 'RFC 2132'),
  (22, 'max_datagram_reassembly_size', 'uint16', 'Specifies the maximum size datagram that the client should be prepared to reassemble, with a minimum legal value of 576.', 'RFC 2132'),
  (23, 'default_ip_ttl', 'uint8', 'Specifies the default time-to-live the client should use on outgoing datagrams.', 'RFC 2132'),
  (24, 'path_mtu_aging_timeout', 'uint32', 'Specifies the timeout, in seconds, the client should use when aging Path MTU values discovered per RFC 1191.', 'RFC 2132'),
  (25, 'path_mtu_plateau_table', 'bytes', 'Specifies a table of MTU sizes, each a 16-bit unsigned integer, to use when performing Path MTU Discovery per RFC 1191. Values are ordered smallest to largest and the table must contain at least one value of 68 or more.', 'RFC 2132'),
  (26, 'interface_mtu', 'uint16', 'Specifies the MTU the client should use on the interface being configured. The minimum legal value is 68.', 'RFC 2132'),
  (27, 'all_subnets_local', 'boolean', 'Specifies whether the client should assume all subnets of its connected network share the same MTU as the local subnet, for the purpose of Path MTU Discovery.', 'RFC 2132'),
  (28, 'broadcast_address', 'ip', 'Specifies the broadcast address in use on the client''s subnet.', 'RFC 2132'),
  (29, 'perform_mask_discovery', 'boolean', 'Specifies whether the client should perform subnet mask discovery using ICMP.', 'RFC 2132'),
  (30, 'mask_supplier', 'boolean', 'Specifies whether the client should respond to ICMP subnet mask requests from other hosts.', 'RFC 2132'),
  (31, 'perform_router_discovery', 'boolean', 'Specifies whether the client should solicit routers using the ICMP Router Discovery protocol defined in RFC 1256.', 'RFC 2132'),
  (32, 'router_solicitation_address', 'ip', 'Specifies the address to which the client should transmit ICMP Router Solicitation requests.', 'RFC 2132'),
  (33, 'static_routes', 'route_list', 'Specifies a list of static routes the client should install in its routing cache, given as destination/router pairs. Routes are listed in order of priority and this option does not support a default route (use option 3 instead).', 'RFC 2132'),
  (34, 'trailer_encapsulation', 'boolean', 'Specifies whether the client should negotiate use of trailers, per RFC 893, when using the ARP protocol.', 'RFC 2132'),
  (35, 'arp_cache_timeout', 'uint32', 'Specifies the timeout, in seconds, for ARP cache entries on the client.', 'RFC 2132'),
  (36, 'ethernet_encapsulation', 'boolean', 'Specifies whether the client should use Ethernet Version 2 (RFC 894) or IEEE 802.3 (RFC 1042) encapsulation when the interface is Ethernet.', 'RFC 2132'),
  (37, 'tcp_default_ttl', 'uint8', 'Specifies the default time-to-live the client should use when sending TCP segments, with a minimum value of 1.', 'RFC 2132'),
  (38, 'tcp_keepalive_interval', 'uint32', 'Specifies the interval, in seconds, the client should wait before sending a TCP keepalive message; a value of zero disables keepalives.', 'RFC 2132'),
  (39, 'tcp_keepalive_garbage', 'boolean', 'Specifies whether the client should send TCP keepalive messages with an octet of garbage data for compatibility with older implementations.', 'RFC 2132'),
  (40, 'nis_domain', 'string', 'Specifies the name of the Network Information Service (NIS) domain the client should use.', 'RFC 2132'),
  (41, 'nis_servers', 'ip_list', 'Lists the IP addresses of Network Information Service (NIS) servers available to the client.', 'RFC 2132'),
  (42, 'ntp_servers', 'ip_list', 'Lists the IP addresses of Network Time Protocol (NTP) servers available to the client.', 'RFC 2132'),
  (43, 'vendor_specific_information', 'bytes', 'Carries vendor-specific information as opaque, vendor-encoded octets that the client and server exchange out of band from other DHCP options.', 'RFC 2132'),
  (44, 'netbios_name_servers', 'ip_list', 'Lists the IP addresses of NetBIOS over TCP/IP name servers (WINS servers) available to the client, in order of preference.', 'RFC 2132'),
  (45, 'netbios_datagram_distribution_server', 'ip_list', 'Lists the IP addresses of NetBIOS over TCP/IP datagram distribution servers available to the client, in order of preference.', 'RFC 2132'),
  (46, 'netbios_node_type', 'uint8', 'Specifies the NetBIOS over TCP/IP node type of the client (1=B-node, 2=P-node, 4=M-node, 8=H-node), which determines how it resolves NetBIOS names.', 'RFC 2132'),
  (47, 'netbios_scope', 'string', 'Specifies the NetBIOS over TCP/IP scope parameter for the client, per RFC 1001/1002.', 'RFC 2132'),
  (48, 'x_window_font_servers', 'ip_list', 'Lists the IP addresses of X Window System font servers available to the client.', 'RFC 2132'),
  (49, 'x_window_display_managers', 'ip_list', 'Lists the IP addresses of X Window System display manager servers available to the client.', 'RFC 2132'),
  (50, 'requested_ip_address', 'ip', 'Used by a client in a DHCPDISCOVER or DHCPREQUEST message to request a specific IP address, typically one previously assigned to it.', 'RFC 2132'),
  (51, 'ip_address_lease_time', 'uint32', 'Specifies the duration, in seconds, of the IP address lease. Used by clients in requests and by servers in offers/acknowledgements.', 'RFC 2132'),
  (52, 'option_overload', 'uint8', 'Signals that the DHCP ''sname'' and/or ''file'' fields are being overloaded to carry additional DHCP options rather than their normal BOOTP meaning.', 'RFC 2132'),
  (53, 'dhcp_message_type', 'uint8', 'Identifies the type of DHCP message being sent (e.g. DISCOVER, OFFER, REQUEST, ACK, NAK, RELEASE, INFORM).', 'RFC 2132'),
  (54, 'server_identifier', 'ip', 'Used in DHCPOFFER and DHCPREQUEST messages to identify the DHCP server, and by clients to distinguish between lease offers from multiple servers.', 'RFC 2132'),
  (55, 'parameter_request_list', 'bytes', 'Sent by the client to request that the server include specific configuration parameters, identified by their option codes, in its reply.', 'RFC 2132'),
  (56, 'message', 'string', 'Carries a human-readable error message, typically used by the server in a DHCPNAK to explain the reason for declining a request.', 'RFC 2132'),
  (57, 'maximum_dhcp_message_size', 'uint16', 'Specifies the maximum length DHCP message the client is willing to accept, with a minimum value of 576 octets.', 'RFC 2132'),
  (58, 'renewal_time', 'uint32', 'Specifies the time interval, in seconds, from address assignment until the client transitions to the RENEWING state (the T1 timer).', 'RFC 2132'),
  (59, 'rebinding_time', 'uint32', 'Specifies the time interval, in seconds, from address assignment until the client transitions to the REBINDING state (the T2 timer).', 'RFC 2132'),
  (60, 'vendor_class_identifier', 'string', 'Used by a client to identify its vendor type and configuration, allowing the server to select vendor-specific options or behavior.', 'RFC 2132'),
  (61, 'client_identifier', 'bytes', 'Uniquely identifies a client on the local network, typically a hardware type/address pair, used by the server to index its database of address bindings.', 'RFC 2132'),
  (64, 'nis_plus_domain', 'string', 'Specifies the name of the NIS+ domain the client should use.', 'RFC 2132'),
  (65, 'nis_plus_servers', 'ip_list', 'Lists the IP addresses of NIS+ servers available to the client.', 'RFC 2132'),
  (66, 'tftp_server_name', 'string', 'Specifies the name of a TFTP server, used when the ''sname'' field in the DHCP header has been overloaded for options.', 'RFC 2132'),
  (67, 'bootfile_name', 'string', 'Specifies the name of the boot file to retrieve, used when the ''file'' field in the DHCP header has been overloaded for options.', 'RFC 2132'),
  (68, 'mobile_ip_home_agent', 'ip_list', 'Lists the IP addresses of Mobile IP home agents available to the client. An empty list indicates no home agents are available on the client''s subnet.', 'RFC 2132'),
  (69, 'smtp_servers', 'ip_list', 'Lists the IP addresses of Simple Mail Transfer Protocol (SMTP) servers available to the client, in order of preference.', 'RFC 2132'),
  (70, 'pop3_servers', 'ip_list', 'Lists the IP addresses of Post Office Protocol (POP3) servers available to the client, in order of preference.', 'RFC 2132'),
  (71, 'nntp_servers', 'ip_list', 'Lists the IP addresses of Network News Transfer Protocol (NNTP) servers available to the client, in order of preference.', 'RFC 2132'),
  (72, 'default_www_servers', 'ip_list', 'Lists the IP addresses of default World Wide Web (HTTP) servers available to the client, in order of preference.', 'RFC 2132'),
  (73, 'default_finger_servers', 'ip_list', 'Lists the IP addresses of default Finger servers available to the client, in order of preference.', 'RFC 2132'),
  (74, 'default_irc_servers', 'ip_list', 'Lists the IP addresses of default Internet Relay Chat (IRC) servers available to the client, in order of preference.', 'RFC 2132'),
  (75, 'streettalk_servers', 'ip_list', 'Lists the IP addresses of StreetTalk servers available to the client.', 'RFC 2132'),
  (76, 'streettalk_directory_assistance_servers', 'ip_list', 'Lists the IP addresses of StreetTalk Directory Assistance (STDA) servers available to the client.', 'RFC 2132'),
  (77, 'user_class', 'bytes', 'Carries one or more opaque user class identifiers set by the client so the server can select configuration appropriate to its user class.', 'RFC 3004'),
  (78, 'slp_directory_agent', 'bytes', 'Identifies Service Location Protocol (SLP) Directory Agents available to the client, encoded as a mandatory flag octet followed by a list of agent addresses.', 'RFC 2610'),
  (79, 'slp_service_scope', 'bytes', 'Carries the Service Location Protocol (SLP) Scope List the client should use, encoded as a mandatory flag octet followed by a scope list string.', 'RFC 2610'),
  (80, 'rapid_commit', 'boolean', 'A zero-length flag option: its mere presence in a DHCPDISCOVER indicates the client supports the Rapid Commit two-message exchange (DHCPDISCOVER/DHCPACK) instead of the normal four-message exchange.', 'RFC 4039'),
  (81, 'client_fqdn', 'fqdn', 'Carries the client''s fully qualified domain name and flags negotiating which party (client or server) performs DNS updates for the client''s A and PTR records.', 'RFC 4702'),
  (82, 'relay_agent_information', 'bytes', 'A container option inserted by a DHCP relay agent that carries sub-options (such as Circuit ID and Remote ID) identifying the client''s attachment point, used for policy decisions and echoed back by the server unchanged.', 'RFC 3046'),
  (83, 'internet_storage_name_service', 'bytes', 'Carries Internet Storage Name Service (iSNS) discovery information, allowing iSCSI and Fibre Channel initiators to locate iSNS servers.', 'RFC 4174'),
  (85, 'nds_servers', 'ip_list', 'Lists the IP addresses of Novell Directory Services (NDS) servers available to the client.', 'RFC 2241'),
  (86, 'nds_tree_name', 'string', 'Specifies the name of the Novell Directory Services (NDS) tree the client should contact.', 'RFC 2241'),
  (87, 'nds_context', 'string', 'Specifies the initial Novell Directory Services (NDS) context the client should use.', 'RFC 2241'),
  (88, 'bcmcs_controller_domain_name_list', 'string', 'Lists the domain names of Broadcast and Multicast Service (BCMCS) controllers available to the client.', 'RFC 4280'),
  (89, 'bcmcs_controller_ipv4_address_list', 'ip_list', 'Lists the IP addresses of Broadcast and Multicast Service (BCMCS) controllers available to the client.', 'RFC 4280'),
  (90, 'authentication', 'bytes', 'Carries a protocol, algorithm, and replay detection method along with authentication information used to authenticate the source and contents of DHCP messages between client and server.', 'RFC 3118'),
  (91, 'client_last_transaction_time', 'uint32', 'Specifies the time, in seconds, since the client''s last transaction with the server, used by failover-capable servers to synchronize lease state.', 'RFC 4388'),
  (92, 'associated_ip', 'ip_list', 'Lists IP addresses associated with a DHCP client''s network interface, used by failover-capable servers exchanging LEASEQUERY information.', 'RFC 4388'),
  (93, 'client_system_architecture', 'uint16', 'Identifies the client system''s architecture type (e.g. BIOS x86, EFI x86-64), allowing a PXE-capable server to select an appropriate boot file.', 'RFC 4578'),
  (94, 'client_network_interface_identifier', 'bytes', 'Identifies the client''s network interface type and revision (UNDI major/minor version), used in PXE boot negotiation.', 'RFC 4578'),
  (95, 'ldap', 'string', 'Carries one or more LDAP server URLs the client should use to bootstrap directory service configuration.', 'RFC 3679'),
  (97, 'client_machine_identifier', 'bytes', 'Carries a client machine identifier (UUID/GUID), consisting of a type octet followed by the identifier, used in PXE boot negotiation.', 'RFC 4578'),
  (98, 'open_group_user_authentication', 'string', 'Specifies the URL of a directory service used for Open Group (formerly the Open Software Foundation) user authentication.', 'RFC 2485'),
  (99, 'geoconf_civic', 'bytes', 'Carries the client''s civic location (e.g. street address) encoded per the GeoConf Civic Address format.', 'RFC 4776'),
  (100, 'pcode', 'string', 'Specifies the client''s POSIX timezone string (the TZ environment variable format, e.g. "EST5EDT"), per the IEEE 1003.1 standard.', 'RFC 4833'),
  (101, 'tcode', 'string', 'Specifies the name of the client''s timezone database entry (e.g. "America/New_York") per the tz (Olson) database.', 'RFC 4833'),
  (108, 'ipv6_only_preferred', 'uint32', 'Signals that the network is IPv6-only capable and specifies, in seconds, how long the client should disable DHCPv4 on this interface (the V6ONLY_WAIT time).', 'RFC 8925'),
  (109, 'dhcp_captive_portal', 'string', 'Specifies the URI of a captive portal the client should present to the user before general network access is available.', 'RFC 8910'),
  (112, 'netinfo_parent_server_address', 'ip_list', 'Lists the IP addresses of NetInfo parent server(s) for a client bootstrapping from a NetInfo server hierarchy.', 'RFC 3679'),
  (113, 'netinfo_parent_server_tag', 'string', 'Specifies the NetInfo parent server tag corresponding to the addresses in option 112.', 'RFC 3679'),
  (114, 'dhcp_captive_portal_legacy', 'string', 'Legacy captive-portal URL option, superseded by option 114''s reassignment (RFC 8910) and originally by option 160; retained here for historical/compatibility reasons.', 'RFC 3679'),
  (115, 'autoconfigure', 'boolean', 'Legacy option instructing a client whether it should use IPv4 Link-Local auto-configuration when no DHCP server responds. Deprecated and largely obsolete.', 'RFC 3679'),
  (116, 'auto_configure', 'boolean', 'Specifies whether the client should perform IPv4 Link-Local address auto-configuration (RFC 3927) if it is unable to contact a DHCP server.', 'RFC 2563'),
  (117, 'name_service_search', 'bytes', 'Carries an ordered list of Name Service Switch database identifiers, specifying the order in which name resolution services should be consulted.', 'RFC 2937'),
  (118, 'subnet_selection', 'ip', 'Allows a DHCP client (typically a relay-like proxy) to specify the subnet on which an address should be allocated, distinct from the giaddr field.', 'RFC 3011'),
  (119, 'domain_search', 'bytes', 'Specifies a list of domain names, encoded using DNS name compression per RFC 1035, that the client should use as its DNS search list.', 'RFC 3397'),
  (120, 'sip_servers', 'bytes', 'Lists SIP outbound proxy servers available to the client, encoded as either domain names or IP addresses per the encoding flag in the option.', 'RFC 3361'),
  (121, 'classless_static_routes', 'route_list', 'Specifies a list of classless static routes (destination prefix and router pairs) the client should install in its routing table; when present, this option takes precedence over options 3 and 33.', 'RFC 3442'),
  (122, 'ccc', 'bytes', 'Carries CableLabs Client Configuration (CCC) sub-options used to configure PacketCable/CableHome devices, such as TFTP server addresses and provisioning timers.', 'RFC 3495'),
  (123, 'geoconf', 'bytes', 'Carries the client''s geographic location (latitude, longitude, altitude) encoded per the GeoConf option format.', 'RFC 6225'),
  (124, 'vendor_identifying_vendor_class', 'bytes', 'Carries one or more vendor-identifying vendor class entries, each tagged with an IANA enterprise number, allowing multi-vendor class identification.', 'RFC 3925'),
  (125, 'vendor_identifying_vendor_specific', 'bytes', 'Carries vendor-specific information tagged with an IANA enterprise number, allowing the server to deliver configuration specific to a particular vendor''s equipment.', 'RFC 3925'),
  (128, 'pxe_undefined_or_etherboot', 'bytes', 'Historically used ambiguously by different PXE/Etherboot implementations (e.g. TFTP Server IP for Etherboot, or DOCSIS full security for cable modems); no single canonical meaning is registered for this code.', 'RFC 4578'),
  (129, 'pxe_call_server_ip', 'bytes', 'Used by some PXE client implementations to carry a call server IP address; not part of the formal PXE specification but seen in vendor deployments.', 'RFC 4578'),
  (130, 'pxe_discrimination_string', 'string', 'Used by some PXE client implementations as a vendor discrimination string to distinguish PXE client types.', 'RFC 4578'),
  (131, 'pxe_remote_stats_server_ip', 'ip', 'Used by some PXE client implementations to carry the IP address of a remote statistics server.', 'RFC 4578'),
  (132, 'pxe_802_1q_vlan_id', 'uint16', 'Used by some PXE client implementations to carry an IEEE 802.1Q VLAN ID to apply on the boot interface.', 'RFC 4578'),
  (133, 'pxe_802_1p_priority', 'uint8', 'Used by some PXE client implementations to carry an IEEE 802.1p Layer 2 priority to apply on the boot interface.', 'RFC 4578'),
  (134, 'pxe_diffserv_code_point', 'uint8', 'Used by some PXE client implementations to carry a Diffserv Code Point for VLAN IP Phones.', 'RFC 4578'),
  (135, 'pxe_http_proxy', 'string', 'Used by some PXE client implementations to carry the URL of an HTTP proxy for use during PXE boot.', 'RFC 4578'),
  (136, 'pana_agent', 'ip_list', 'Lists the IP addresses of PAA (PANA Authentication Agent) servers available to the client.', 'RFC 5192'),
  (137, 'v4_lost', 'fqdn', 'Specifies the domain name of a LoST (Location-to-Service Translation) server the client should use to map location information to service URIs.', 'RFC 5223'),
  (138, 'capwap_ac_v4', 'ip_list', 'Lists the IP addresses of CAPWAP (Control and Provisioning of Wireless Access Points) Access Controllers available to the client.', 'RFC 5417'),
  (139, 'mos_address', 'bytes', 'Carries IPv4 addresses of MoS (Media Operations Server) address enumerators, encoded per the MoS option format.', 'RFC 5678'),
  (140, 'mos_domain_name', 'bytes', 'Carries FQDN-based MoS (Media Operations Server) domain name enumerators, encoded per the MoS option format.', 'RFC 5678'),
  (141, 'sip_ua_configuration_domains', 'bytes', 'Lists the domain names of SIP User Agent (UA) configuration service domains, encoded using DNS name compression, that the client should use for provisioning.', 'RFC 6011'),
  (142, 'ipv4_address_andsf', 'ip_list', 'Lists the IP addresses of ANDSF (Access Network Discovery and Selection Function) servers available to the client.', 'RFC 6153'),
  (143, 'geolock', 'bytes', 'Carries geographic-location-bound configuration data used to restrict configuration to a defined geographic area (GeoLoc option).', 'RFC 7658'),
  (144, 'forcerenew_nonce_capable', 'bytes', 'Signals that the client supports the FORCERENEW_NONCE authentication protocol for the DHCP FORCERENEW message.', 'RFC 6704'),
  (145, 'rdnss_selection', 'bytes', 'Carries Recursive DNS Server (RDNSS) selection information, mirroring the IPv6 RDNSS Selection option for use in DHCPv4 environments alongside RAs.', 'RFC 6731'),
  (146, 'v4_dots_ri', 'string', 'Carries the DDoS Open Threat Signaling (DOTS) Reference Identifier the client should use to identify itself to a DOTS server.', 'RFC 8973'),
  (147, 'v4_dots_address', 'ip_list', 'Lists the IP addresses of DDoS Open Threat Signaling (DOTS) agents available to the client.', 'RFC 8973'),
  (150, 'tftp_server_address', 'ip_list', 'Lists TFTP server addresses; also used by some Cisco VoIP deployments to carry the call manager address list under this code.', 'RFC 5859'),
  (151, 'status_code', 'bytes', 'Carries a status code and optional message used in DHCP Bulk Leasequery and Active Leasequery exchanges to indicate the outcome of a query.', 'RFC 6926'),
  (152, 'base_time', 'uint32', 'Specifies the base time, in seconds since the epoch, that other Leasequery time-relative options are computed from.', 'RFC 6926'),
  (153, 'start_time_of_state', 'uint32', 'Specifies the number of seconds since base_time (option 152) at which the reported lease state began, used in DHCP Leasequery.', 'RFC 6926'),
  (154, 'query_start_time', 'uint32', 'Specifies the start of a time range, in seconds since the epoch, for a DHCP Active Leasequery request.', 'RFC 6926'),
  (155, 'query_end_time', 'uint32', 'Specifies the end of a time range, in seconds since the epoch, for a DHCP Active Leasequery request.', 'RFC 6926'),
  (156, 'dhcp_state', 'uint8', 'Reports the state of a lease (e.g. available, active, expired, released) in a DHCP Leasequery response.', 'RFC 6926'),
  (157, 'data_source', 'uint8', 'Indicates whether the data in a DHCP Leasequery response came from local information or was received via failover from a partner server.', 'RFC 6926'),
  (158, 'v4_pcp_server', 'ip_list', 'Lists the IP addresses of Port Control Protocol (PCP) servers available to the client.', 'RFC 7291'),
  (159, 'v4_portparams', 'bytes', 'Carries Port Parameters (offset, PSID length, and PSID) used to configure a client for shared IPv4 address / restricted port range scenarios.', 'RFC 7618'),
  (160, 'dhcp_captive_portal_deprecated', 'string', 'Originally assigned for a DHCP Captive-Portal URL; deprecated and reassigned as option 114 in RFC 8910. Some legacy deployments may still use this code.', 'RFC 8910'),
  (175, 'etherboot', 'bytes', 'Unofficially used by the Etherboot/gPXE project to carry vendor-specific configuration; not part of the formal IANA registry semantics but observed in real deployments.', 'RFC 3679'),
  (176, 'ip_telephone', 'bytes', 'Unofficially used by some IP telephony equipment vendors (e.g. for configuration bootstrap); not part of the formal IANA registry semantics but observed in real deployments.', 'RFC 3679'),
  (177, 'etherboot_pxe', 'bytes', 'Unofficially used by some Etherboot/PXE client implementations, overlapping in some deployments with option 176 usage; not part of the formal IANA registry semantics.', 'RFC 3679'),
  (208, 'pxelinux_magic', 'bytes', 'Carries a magic number (0xF1 0x00 0x74 0x7E) used by PXELINUX to detect whether a DHCP/BOOTP reply was tagged with PXELINUX-specific options.', 'RFC 5071'),
  (209, 'pxelinux_configfile', 'string', 'Specifies the configuration file path PXELINUX should use, overriding its default configuration file discovery behavior.', 'RFC 5071'),
  (210, 'pxelinux_pathprefix', 'string', 'Specifies a path prefix PXELINUX should use when locating configuration and other files, overriding its default TFTP path behavior.', 'RFC 5071'),
  (211, 'pxelinux_reboottime', 'uint32', 'Specifies, in seconds, how long PXELINUX should wait before rebooting the client after a fatal error.', 'RFC 5071'),
  (212, 'option_6rd', 'bytes', 'Carries IPv6 Rapid Deployment (6rd) configuration parameters (IPv4 mask length, 6rd prefix, and Border Relay addresses) for automatic IPv6-over-IPv4 tunneling.', 'RFC 5969'),
  (213, 'v4_access_domain', 'fqdn', 'Specifies the access network domain name the client should associate with, used in some access-network-aware deployments.', 'RFC 5986'),
  (220, 'subnet_allocation', 'bytes', 'Carries Subnet Allocation option data used by some access-concentrator deployments to signal subnet assignment parameters to the client.', 'RFC 6656'),
  (221, 'virtual_subnet_selection', 'bytes', 'Carries Virtual Subnet Selection (VSS) information identifying a VPN routing/forwarding instance the requested address should be allocated from.', 'RFC 6607'),
  (249, 'ms_classless_static_routes', 'route_list', 'A Microsoft-specific classless static routes option (functionally identical to the standard option 121), used because older Windows DHCP clients only recognized this pre-standardization code.', 'Unassigned (Microsoft de facto)'),
